import{_ as a,o as n,c as o,j as e,a as r}from"./chunks/framework.Bd7kzaCy.js";const h=JSON.parse('{"title":"D.05　信息、表示、数学与物理借用","description":"","frontmatter":{"title":"D.05　信息、表示、数学与物理借用"},"headers":[],"relativePath":"theory/appendix-d/d-05.md","filePath":"theory/appendix-d/d-05.md"}'),d={name:"theory/appendix-d/d-05.md"};function l(s,t,p,i,c,u){return n(),o("div",null,[...t[0]||(t[0]=[e("div",{class:"theory-source"},[e("h1",{id:"section-d-05",tabindex:"-1"},[r("D.05　信息、表示、数学与物理借用 "),e("a",{class:"header-anchor",href:"#section-d-05","aria-label":'Permalink to "D.05　信息、表示、数学与物理借用 {#section-d-05}"'},"​")]),e("p",null,"正文连接：§2.6、2.8；§4.6、4.8；§5；附录C。研究入口：05.01—05.08。"),e("p",null,"表示需要相对于问题评价。源状态能否恢复、指定任务能否完成、计算成本是否可承受、未来动态是否闭合，以及允许干预后是否仍充分，是五个不同维度。源信息减少不必导致当前任务失败；任务充分也不能被外推为全部未来问题充分。"),e("p",null,"形式上，存在函数g使q=g∘f，当且仅当q在f的每个原像集合上取相同值；这首先是表示充分性的判据，实际可计算性另行判断。这个判据使抽象具有正面成立条件，而不只留下损失警告。若仅一个隐藏份额影响干预后结果，可以补入该份额；不必一旦闭合失败就无止境恢复所有细节。实际采用还应计入测量、隐私、维护和理解成本。"),e("p",null,"单位换算、会计恒等、经验转换率和价值权重分别成立。能量或物质守恒须有正确边界与量纲；社会负担、痛苦、注意力和道德责任没有因共享“负荷”一词就获得守恒律。消除重复劳动、改善技术或减少伤害，可以真实降低成本，不必被解释成成本必然转移到别处。"),e("p",null,"哥德尔、不完备性与可计算性的结果依赖特定形式系统及问题类别，不能推出每个有限任务都无法判断。模型简约也不只看参数数目：整个选择过程、搜索过的表示、调参预算及目标变化都应计入比较。物理或数学成果可提供精确的桥接纪律，不能以声望代替目标域的经验前提。"),e("p",null,"多次转换必须保持同一个最终问题。若第一步已经充分，第二步仍须在实际可达的中间表示上保留最终答案所需区别；分别完成两个不同的局部任务，不能证明接续后仍回答原问题。答案函数存在、有效算法存在、预算内可算、资料及时可达和实际使用正确分别检查。有限完整表可以查表，一般无限域则不能由信息未丢失推出总停止算法。"),e("p",null,"专题定位：05.01 Shannon 信息论、信道与噪声；05.02 压缩、表示与有损转义；05.03 熵、耗散结构与社会秩序类比；05.04 守恒、势场、力与承载的借用；05.05 哥德尔、不完备性与可计算性；05.06 有效理论、尺度闭合与粗粒化；05.07 信息本体、量子与宇宙类比的历史退场；05.08 模型选择、简约与表达能力。")],-1)])])}const m=a(d,[["render",l]]);export{h as __pageData,m as default};
